from copy import deepcopy

def merge_layers(base, override):
    result = deepcopy(base)
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict):
            previous = result.get(key)
            result[key] = merge_layers(previous if isinstance(previous, dict) else {}, value)
        else:
            result[key] = deepcopy(value)
    return result

def allocate_cents(total, weights):
    if not weights:
        return []
    denominator = sum(weights)
    parts = [divmod(total * weight, denominator) for weight in weights]
    result = [part[0] for part in parts]
    order = sorted(range(len(weights)), key=lambda i: (-parts[i][1], i))
    for index in order[:total - sum(result)]:
        result[index] += 1
    return result

from heapq import heapify, heappop, heappush

def topo_order(nodes, edges):
    outgoing = {node: set() for node in nodes}
    degrees = {node: 0 for node in nodes}
    for before, after in edges:
        if after not in outgoing[before]:
            outgoing[before].add(after)
            degrees[after] += 1
    ready = [node for node in nodes if degrees[node] == 0]
    heapify(ready)
    result = []
    while ready:
        node = heappop(ready)
        result.append(node)
        for after in sorted(outgoing[node]):
            degrees[after] -= 1
            if degrees[after] == 0:
                heappush(ready, after)
    return result if len(result) == len(nodes) else []

import re

def parse_release(value):
    core = r'(0|[1-9][0-9]*)'
    identifier = r'[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*'
    match = re.fullmatch(r'v?' + core + r'\.' + core + r'\.' + core + r'(?:-(' + identifier + r'))?(?:\+(' + identifier + r'))?', value.strip(), flags=re.ASCII)
    if match is None:
        return None
    pre = match.group(4).split('.') if match.group(4) else []
    if any(part.isdigit() and len(part) > 1 and part.startswith('0') for part in pre):
        return None
    return {'major':int(match.group(1)),'minor':int(match.group(2)),'patch':int(match.group(3)),'prerelease':pre,'build':match.group(5).split('.') if match.group(5) else []}
